+impl<'v, 's> PassTSession<'v, 's> {
+    pub fn begin(
+        domain: GrammarDomain,
+        view: &'v super::owner_ext_type_builder::CheckedTypeDeclView<'v>,
+        functions: &'s [super::owner_ext_t3_uses::ExtFunction],
