+        Ok(Self {
+            view,
+            builder,
+            walker: T3UseWalker::new(functions, entry),
+            locator,
+            records: Vec::new(),
+            poisoned: false,
+        })
+    }
+
+    pub fn process_next_use(
+        &mut self,
+    ) -> Result<Option<super::owner_ext_t3_uses::T3Record>, super::owner_ext_type_builder::ExtTypeBuildError> {
